// The statistics of a box plot: R's boxplot.stats (grDevices).
//
// Written for rStats.js to reproduce R's documented behaviour and output (experiments/plot121-log.md, experiments 1
// and 2): Tukey's hinges (fivenum), whiskers to the most extreme values within coef times the hinge spread of the
// box, the notch median +- 1.58 (hinge spread) / sqrt(n), and the values beyond the whiskers.
import { fivenum } from "./quantile.js";
import type { Sample } from "../htest/types.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const BOXPLOT_STATS_KEYS = ["coef", "doConf", "doOut"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/**
 * Options for {@link boxplotStats}.
 *
 * @category Descriptive statistics
 */
export interface BoxplotStatsOptions {
  /** How far the whiskers reach, in hinge spreads. Default `1.5`; `0` puts them at the extremes (no outliers). */
  coef?: number;
  /** Compute the notch interval `conf`. Default `true`. */
  doConf?: boolean;
  /** Return the outliers `out`. Default `true`. */
  doOut?: boolean;
}

/**
 * The result of {@link boxplotStats}.
 *
 * @category Descriptive statistics
 */
export interface BoxplotStatsResult {
  /** The lower whisker, the lower hinge, the median, the upper hinge and the upper whisker (NaN for no values). */
  stats: [number, number, number, number, number];
  /** The number of values that are not missing. */
  n: number;
  /** The notch: median -+ 1.58 times the hinge spread over sqrt(n) (empty with `doConf: false`). */
  conf: number[];
  /** The values beyond the whiskers, in the order given (empty with `doOut: false` or `coef: 0`). */
  out: number[];
}

/**
 * The statistics a box plot draws. Equivalent to R's `boxplot.stats()`. Missing values (NaN) are dropped; infinite
 * values are values like any other (so they are outliers).
 *
 * @example
 * ```ts
 * boxplotStats([1, 2, 3, 4, 5, 40]); // { stats: [1, 2, 3.5, 5, 5], n: 6, conf: [...], out: [40] }
 * ```
 *
 * @throws RangeError for a negative `coef`.
 * @category Descriptive statistics
 */
export function boxplotStats(x: Sample, options: BoxplotStatsOptions = {}): BoxplotStatsResult {
  checkOptions(options, BOXPLOT_STATS_KEYS, "boxplotStats"); // generated: option-keys.mjs
  const coef = options.coef ?? 1.5;
  if (!(coef >= 0)) throw new RangeError("'coef' must not be negative");
  const v = Array.from(x).filter((t) => !Number.isNaN(t));
  const n = v.length;
  const stats = fivenum(v);
  const spread = stats[3] - stats[1];
  let out: number[] = [];
  if (coef > 0 && n > 0) {
    const lo = stats[1] - coef * spread, hi = stats[3] + coef * spread;
    const inside = v.filter((t) => t >= lo && t <= hi);
    out = v.filter((t) => t < lo || t > hi);
    if (inside.length > 0) {
      stats[0] = Math.min(...inside);
      stats[4] = Math.max(...inside);
    }
  }
  const half = (1.58 * spread) / Math.sqrt(n);
  return {
    stats,
    n,
    conf: (options.doConf ?? true) ? [stats[2] - half, stats[2] + half] : [],
    out: (options.doOut ?? true) ? out : [],
  };
}
